        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _sessionToRevoke = null;
        }
        catch
        {
            // Keep dialog open on failure
        }
        finally
        {
            _revoking = false;
        }
    }
}
"}

{"path": "/tmp/sv-10ff58258697497d8b1baa76c872bd41/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_10ff58258697497d8b1baa76c872bd41.Components.Pages.Settings
@using sv_10ff58258697497d8b1baa76c872bd41.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        @if (_loading)
        {
            <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            <div class="row">
                <div class="col-md-7">
                    @* Theme *@
                    <div class="mb-4">
                        <h6>Theme</h6>
                        <div class="btn-group" role="group">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                            }
                        </div>
                    </div>

                    @* Font Size *@
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        <div class="btn-group" role="group">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                <input type="radio" class="btn-check" name="fontSize" id="@($"fs-{size}")"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="btn btn-outline-secondary" for="@($"fs-{size}")">@size</label>
                            }
                        </div>
                    </div>

                    @* Language *@
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" style="max-width:250px;" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>
                </div>

                @* Live Preview *@
                <div class="col-md-5">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyle()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is a preview of how your content will look with the selected appearance settings.
                        </p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <div class="mt-2">
                            <small class="text-muted" style="@GetPreviewFontStyle()">
                                Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "On" : "Off")
                            </small>
                        </div>
                    </div>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        }
    </div>
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        return _theme switch
        {
            "Dark" => "bg-dark text-light",
            "Light" => "bg-white text-dark",
            _ => "bg-body text-body"
        };
    }

    private string GetPreviewStyle()
    {
        return _compactMode ? "padding: 0.5rem !important;" : "";
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size:{size};";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}
"}

